window.BUCH = {"content":{"musik":{"lautstaerke":0.5},"cover":{"titel":"Happy Birthday\nMarie","untertitel":"Band 27","bild":"cover.jpg","fokus":"60% 30%"},"widmung":{"titel":"Wie wir uns kennengelernt haben","avatare":{"ich":"avatar-burak.jpg","sie":"avatar-marie.jpg"},"chat":[{"typ":"hinweis","text":"Du hast auf ihre Story geantwortet","rechts":true},{"typ":"story","text":"Story nicht verfügbar."},{"von":"ich","text":"Liest du aktuell ein Buch? Voll Random die Frage, aber habe das bei dir da im anderen Video gesehen und wollte fragen welches das ist 😂"},{"typ":"zeit","text":"20. Sept., 13:12"},{"typ":"hinweis","text":"Nachrichtenanfrage angenommen. Du kannst eine Unterhaltung beginnen."},{"von":"sie","text":"Hey:) in welchem tiktok meinst du?"},{"typ":"zeit","text":"20. Sept., 13:18"},{"von":"ich","text":"Olaa, dein aller erstes, zweite Bild"},{"von":"ich","text":"Oder soll das als Zitat dienen einfach? 😅"},{"typ":"zeit","text":"20. Sept., 13:37"},{"von":"sie","text":"Ja doch das Buch habe ich gelesen, aber ich kann dir gerade nicht aus dem Kopf sagen aus welchem das Zitat war, aber ich schaue später mal nach🤲🏼","reaktion":"❤️"}]},"kapitel":{"label":"Kapitel 27","titel":"Happy Birthday Mrs.","text":["Olaaaa, ich weiß, wir kennen uns noch kaum, aber wir sind dabei, uns kennenzulernen. Was ich über dich schon sagen kann: Du bist jedes Wochenende am Feiern 🎉, musst ab und zu mal an der Heilpflanze ziehen 🌿🚬, um chillen zu können, bist aktuell schwanger 🤰 und willst natürlich 10 Kinder. Ich bin bereit, dich bei allem zu unterstützen, aber so, wie wir es abgemacht haben: abwechseln, sonst ist es nicht fair 😂🤝","Der erste Eindruck zählt bei Menschen. Meiner von dir: sehr mutig, ehrlich, positiv, selbstständig (frag mich ab jetzt nach Hilfe, okay? 😂). Da gibt es noch mehr, aber nicht übertreiben mit Komplimenten 😂","Du hast trotz alledem auch eine verletzliche Seite. Dir wurde mal dein Strahlen genommen. Jetzt hast du es wieder, und lass es dir nie wieder von irgendjemandem nehmen, egal wer es sein sollte.","Ich respektiere dich ernsthaft: deine Arbeit, deinen Mut, deine Stärke. Du hast bestimmt viele Kämpfe in deinem Kopf, die aktuell niemand hört, und trotzdem schlägst du dich sehr positiv durch.","Happy Birthday, Marie! Lass dich feiern und genieß die Zeit mit deiner Familie und deinen Freunden (ich weiß, mit deinen Freundinnen dauert es noch ein bisschen). Ich bete für dich 🤲.","Lächle immer, egal in welcher Situation. Dein Lächeln, woooow, sehr attraktiv 😊"],"collage":{"titel":"","bilder":[{"bild":"collage-1.jpg","fokus":"50% 30%"},{"bild":"3_fertig.png","ganz":true},{"bild":"collage-2.jpg","fokus":"45% 30%"}],"unterschrift":"Genau das meine ich! Strahlen & Lächeln. Hör niemals auf damit 😊🧿"}},"geschenk":{"label":"Geschenk","hinweis":"Tippen zum Öffnen","titel":"Dein Geschenk","code":"[CODE]","buttonText":"Code kopieren","kopiertText":"Kopiert ✓","emojis":["🎉","🥳","🎂","🎈","🎁","✨"]},"rueckseite":{"bild":"letzte-seite.png","sprachnachricht":{"datei":"sprachnachricht.mp3","dauer":"0:07"}},"akzente":{"cover":"🎈","chat":"🥳","kapitel":["🎂","🎁","✨"],"collage":"🎊","geschenk":"🎀"},"ui":{"blaetternHinweis":"Wischen oder tippen"}},"images":{"cover.jpg":"data:image/jpeg;base64,","collage-1.jpg":"data:image/jpeg;base64,","3_fertig.png":"data:image/jpeg;base64,","collage-2.jpg":"data:image/jpeg;base64,","letzte-seite.png":"data:image/jpeg;base64,","avatar-burak.jpg":"data:image/jpeg;base64,","avatar-marie.jpg":"data:image/jpeg;base64,"},"hasAudio":false};
